// Extract clean message data from Meta's webhook payload.
// Meta also POSTs delivery/read status updates - we ignore those.
const body = $input.first().json.body || $input.first().json;
const cfg = $input.first().json;

let value;
try {
  value = body.entry[0].changes[0].value;
} catch (e) {
  return []; // not a message payload
}

// Status updates (sent/delivered/read) have no 'messages' array
if (!value.messages || !value.messages.length) {
  return [];
}

const message = value.messages[0];
const contact = (value.contacts && value.contacts[0]) || {};

const out = {
  phoneNumberId: cfg.phoneNumberId,
  sheetId: cfg.sheetId,
  adminPhone: cfg.adminPhone,
  litellmUrl: cfg.litellmUrl,
  litellmKey: cfg.litellmKey,
  model: cfg.model,
  from: message.from,
  msgId: message.id,
  msgType: message.type,
  timestamp: message.timestamp,
  displayName: (contact.profile && contact.profile.name) || message.from,
  textContent: '',
  mediaId: null,
  fileName: null,
  mimeType: null
};

if (message.type === 'text') {
  out.textContent = (message.text && message.text.body) || '';
} else if (message.type === 'document') {
  out.mediaId = message.document && message.document.id;
  out.fileName = (message.document && message.document.filename) || 'document.pdf';
  out.mimeType = (message.document && message.document.mime_type) || 'application/pdf';
  out.textContent = (message.document && message.document.caption) || '';
} else if (message.type === 'image') {
  out.mediaId = message.image && message.image.id;
  out.fileName = 'photo_' + message.id.slice(-8) + '.jpg';
  out.mimeType = 'image/jpeg';
  out.textContent = (message.image && message.image.caption) || '';
} else {
  // audio / video / sticker / location etc - treat as OTHER text
  out.textContent = '(' + message.type + ' message)';
}

return [{ json: out }];

// Match the sender's phone against the Files sheet and build full context.
const msg = $('Extract Message').first().json;
const rows = $input.all().map(i => i.json);

const norm = p => String(p || '').replace(/[^0-9]/g, '');
const row = rows.find(r => norm(r.phone) === norm(msg.from));

if (!row) {
  return [{ json: { ...msg, found: false } }];
}

const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);
const allDocs = split(row.required_docs);
const receivedDocs = split(row.received_docs);
const pendingDocs = allDocs.filter(d => !receivedDocs.includes(d));

return [{ json: {
  ...msg,
  found: true,
  clientName: row.name || msg.displayName,
  fileRef: row.file_ref || '',
  ownerPhone: norm(row.owner_phone),
  allDocs, receivedDocs, pendingDocs,
  rowStatus: row.status || 'PENDING'
} }];

const d = $input.first().json;

const system = `You classify WhatsApp messages in a loan/insurance document-collection conversation.

Output ONLY this exact format, nothing else:
{"intent":"VALUE"}

Replace VALUE with exactly one of:
DOCUMENT_SENT - user is sending or has attached a file, photo, or document
ASKING_QUESTION - user asks what documents are needed, format, deadline, or process
DELAY_PROMISE - user says they will send later, need more time, or are busy
ALREADY_SENT - user claims they already sent something previously
GREETING - only hello, hi, thanks, ok, fine, noted
OTHER - anything else

Examples (copy this exact output format):
"Sending bank statement now" -> {"intent":"DOCUMENT_SENT"}
"Ye lo meri salary slip" -> {"intent":"DOCUMENT_SENT"}
"yahan hai document" -> {"intent":"DOCUMENT_SENT"}
"bhej raha hoon" -> {"intent":"DOCUMENT_SENT"}
"Which months bank statement?" -> {"intent":"ASKING_QUESTION"}
"Konsa format chahiye?" -> {"intent":"ASKING_QUESTION"}
"kya kya documents chahiye?" -> {"intent":"ASKING_QUESTION"}
"Will send tomorrow" -> {"intent":"DELAY_PROMISE"}
"kal bhejta hoon" -> {"intent":"DELAY_PROMISE"}
"thoda time do" -> {"intent":"DELAY_PROMISE"}
"abhi busy hoon, baad mein bhejta hoon" -> {"intent":"DELAY_PROMISE"}
"I already sent everything" -> {"intent":"ALREADY_SENT"}
"maine kal hi bhej diya tha" -> {"intent":"ALREADY_SENT"}
"pehle hi send kar diya" -> {"intent":"ALREADY_SENT"}
"Hi" -> {"intent":"GREETING"}
"ok thanks" -> {"intent":"GREETING"}
"theek hai" -> {"intent":"GREETING"}

IMPORTANT: Output ONLY the JSON. No explanation. No markdown. No backticks.`;

const userMsg = `Message type: ${d.msgType}\nMessage text: ${d.textContent || '(no text, file attached)'}`;

return [{ json: {
...d,
llmBody: {
model: d.model,
temperature: 0,
max_tokens: 20,
messages: [
{ role: 'system', content: system },
{ role: 'user', content: userMsg }
],
user: d.from,
metadata: {
generation_name: 'doc-chaser-classify',
session_id: 'wa-' + d.from,
tags: ['agentos', 'doc-chaser']
}
}
} }];

const ctx = $('Build Classify Request').first().json;
const resp = $input.first().json;

const VALID = ['DOCUMENT_SENT','ASKING_QUESTION','DELAY_PROMISE','ALREADY_SENT','GREETING','OTHER'];
let intent = 'OTHER';

try {
  let content = resp.choices[0].message.content.trim();

  // Strip markdown fences and backticks using split/join to avoid backtick in regex
  content = content.split('```json').join('').split('```').join('').trim();

  // Extract just the JSON object
  const match = content.match(/\{[^}]+\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    if (VALID.includes(parsed.intent)) {
      intent = parsed.intent;
    }
  }
} catch (e) {
  intent = 'OTHER';
}

// Hard rule 1: actual file attached = always DOCUMENT_SENT
if (ctx.msgType === 'document' || ctx.msgType === 'image') {
  intent = 'DOCUMENT_SENT';
}

// Hard rule 2: text claiming to send but no actual file
const hasActualFile = !!(ctx.mediaId);
const isClaimingDocument = (intent === 'DOCUMENT_SENT' && !hasActualFile);

const { llmBody, ...clean } = ctx;
return [{ json: { 
  ...clean, 
  intent,
  hasActualFile,
  isClaimingDocument
} }];

const d = $input.first().json;

// CASE A: Client said they're sending but no actual file attached
if (d.isClaimingDocument) {
  const pendingList = d.pendingDocs.map(function(x, i) { return (i+1) + '. ' + x; }).join('\n');
  const replyText = 'Thanks ' + d.clientName + '! We noticed you mentioned sending documents but no file was attached.\n\nPlease send the actual PDF or photo as an attachment in WhatsApp. Still waiting for:\n' + pendingList;

  return [{ json: {
    ...d,
    isClaimingDocument: true,
    clientReply: replyText,
    ownerNote: null,
    isComplete: false,
    newReceived: d.receivedDocs,
    pendingAfter: d.pendingDocs
  }}];
}

// CASE B: Actual file attached — match to pending document
const fname = (d.fileName || '').toLowerCase();
const ftext = (d.textContent || '').toLowerCase();
const combined = fname + ' ' + ftext;

const guess = d.pendingDocs.find(function(doc) {
  const k = doc.toLowerCase();
  return (
    (k.includes('bank statement') && (combined.includes('bank') || combined.includes('statement') || combined.includes('hdfc') || combined.includes('sbi') || combined.includes('icici') || combined.includes('axis')))
    || (k.includes('salary slip') && (combined.includes('salary') || combined.includes('payslip') || combined.includes('pay slip')))
    || (k.includes('form 16') && (combined.includes('form16') || combined.includes('form 16') || combined.includes('16')))
    || (k.includes('itr') && (combined.includes('itr') || combined.includes('income tax')))
    || (k.includes('aadhaar') && (combined.includes('aadhaar') || combined.includes('aadhar') || combined.includes('uid')))
    || (k.includes('pan') && (combined.includes('pan')))
    || (k.includes('business registration') && (combined.includes('registration') || combined.includes('gst') || combined.includes('udyam')))
    || (k.includes('photo') && (combined.includes('photo') || combined.includes('image') || combined.includes('pic')))
  );
});

const receivedLabel = guess || null;
let clientReply;
let newReceived;
let pendingAfter;
let isComplete;

if (!receivedLabel) {
  const pendingList = d.pendingDocs.map(function(x, i) { return (i+1) + '. ' + x; }).join('\n');
  clientReply = 'Thank you for sending a file ' + d.clientName + '! We received it but could not automatically identify which document it is.\n\nWe will review it shortly. Still awaiting:\n' + pendingList + '\n\nIf you can mention which document this is, it helps us process faster!';
  newReceived = d.receivedDocs;
  pendingAfter = d.pendingDocs;
  isComplete = false;
} else {
  newReceived = Array.from(new Set(d.receivedDocs.concat([receivedLabel])));
  pendingAfter = d.allDocs.filter(function(doc) { return !newReceived.includes(doc); });
  isComplete = pendingAfter.length === 0;

  if (isComplete) {
    clientReply = 'Thank you ' + d.clientName + '! All documents for file ' + d.fileRef + ' are now received. Your file is complete and moves to processing. We will be in touch soon!';
  } else {
    const pendingList = pendingAfter.map(function(x, i) { return (i+1) + '. ' + x; }).join('\n');
    clientReply = 'Received your ' + receivedLabel + '! Still pending for file ' + d.fileRef + ':\n' + pendingList + '\n\nPlease send these when convenient.';
  }
}

const ownerNote = d.fileRef + ' | ' + d.clientName + '\nReceived: ' + (receivedLabel || 'UNIDENTIFIED FILE') + '\n' + (isComplete ? 'FILE COMPLETE' : 'Pending: ' + pendingAfter.join(', '));

return [{ json: { 
  ...d,
  receivedLabel,
  newReceived,
  pendingAfter,
  isComplete,
  clientReply,
  ownerNote,
  isClaimingDocument: false
}}];

// Build the answer-a-question LLM request.
const d = $input.first().json;

const system = `You are the document-collection assistant of a financial services firm, replying on WhatsApp. Answer the client's question briefly and politely (max 3 short sentences, you may use one emoji). Use the pending-documents context. If the question is outside document collection, say their advisor will follow up personally. NEVER give financial, tax or loan advice. Reply in the same language the client used (English or Hindi/Hinglish).`;

const userMsg = `Client name: ${d.clientName}\nFile ref: ${d.fileRef}\nPending documents: ${d.pendingDocs.join(', ') || 'none'}\nClient question: ${d.textContent}`;

return [{ json: { ...d, llmBody: {
  model: d.model,
  temperature: 0.3,
  max_tokens: 180,
  messages: [ { role: 'system', content: system }, { role: 'user', content: userMsg } ],
  user: d.from,
  metadata: { generation_name: 'doc-chaser-answer', session_id: 'wa-' + d.from, tags: ['agentos','doc-chaser'] }
} } }];

// Decide who gets a reminder today and pre-build each WhatsApp payload.
const cfg = $('CONFIG (Reminders)').first().json;
const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json);
const norm = p => String(p || '').replace(/[^0-9]/g, '');
const split = s => String(s || '').split(',').map(x => x.trim()).filter(Boolean);

const due = [];
for (const row of rows) {
  if (!row.phone) continue;
  if (String(row.status).toUpperCase() === 'COMPLETE') continue;
  const next = String(row.next_reminder || '').slice(0, 10) || today;
  if (next > today) continue;
  const count = parseInt(row.reminder_count || '0', 10) || 0;
  if (count >= 5) continue; // stop nagging after 5 reminders; owner should call

  const allDocs = split(row.required_docs);
  const received = split(row.received_docs);
  const pending = allDocs.filter(d => !received.includes(d));
  if (!pending.length) continue;

  const text = `Hi ${row.name || 'there'} 👋 Gentle reminder for your file ${row.file_ref || ''} — we\u2019re still waiting on:\n${pending.map((d,i)=>`${i+1}. ${d}`).join('\n')}\n\nJust reply to this message with the documents (PDF or photo). Need help? Ask here anytime. 🙏`;

  due.push({ json: {
    phoneNumberId: cfg.phoneNumberId,
    phone: norm(row.phone),
    name: row.name,
    newCount: count + 1,
    waBody: { messaging_product: 'whatsapp', to: norm(row.phone), type: 'text', text: { body: text } }
  } });
}
return due;
